import React from 'react';
import { Tag } from '@hexa-ui/icons';
import { Paragraph } from '../typography';
import {
  BadgeCounterContainer,
  BadgeStatusContainer,
  BadgeCategoryContainer,
  IconContainer,
} from './Badge.styles';
import { BadgeCounterTypes, BadgeStatusTypes, BadgeCategoryTypes } from './Badge.types';

const Counter = ({
  size = 'small',
  counterLabel = 0,
  ...props
}: BadgeCounterTypes): JSX.Element => (
  <BadgeCounterContainer {...props} size={size}>
    <Paragraph selectable="false">{counterLabel}</Paragraph>
  </BadgeCounterContainer>
);

const Status = ({
  type = 'default',
  color = 'blue',
  label = 'Label',
  disabled = false,
  ...props
}: BadgeStatusTypes): JSX.Element => (
  <BadgeStatusContainer
    disabled={disabled}
    type={disabled ? 'default' : type}
    color={color}
    {...props}
    onClick={disabled ? undefined : props?.onClick}
  >
    <Paragraph selectable="false" css={{ lineHeight: '$3' }} size="small" weight="medium">
      {label}
    </Paragraph>
  </BadgeStatusContainer>
);

const Category = ({
  type = 'default',
  color = 'black',
  label = 'Label',
  disabled = false,
  icon: Icon = Tag,
  ...props
}: BadgeCategoryTypes): JSX.Element => (
  <BadgeCategoryContainer
    color={color}
    disabled={disabled}
    type={disabled ? 'default' : type}
    {...props}
    onClick={disabled ? undefined : props?.onClick}
  >
    <IconContainer color={color}>
      <Icon size="tiny" />
    </IconContainer>
    <Paragraph
      selectable="false"
      css={{ lineHeight: '$3', paddingLeft: '$1' }}
      size="small"
      weight="medium"
    >
      {label}
    </Paragraph>
  </BadgeCategoryContainer>
);

export { Counter, Status, Category };
